/**
 * Student card, front and back, at real size (85.6 × 54 mm landscape / 54 × 85.6 mm portrait). Built from live data:
 * crest from the school settings, photo, name, NIS, card number, validity and a QR generated by the system.
 * Class is not printed unless the template asks for it.
 */
import React from 'react'
import type { CardTemplateSettings } from '@/db/schema'
import { fmtDate } from '@/server/time'
import { fileUrl, P, publicFileUrl } from './kit'
import type { Branding } from '@/server/settings'

export type CardData = {
  name: string
  nis: string | null
  nisn: string | null
  entryYear: number | null
  homeroom?: string | null
  photo: string | null
  cardNo: string
  validUntil: string
  qr: string // SVG markup generated server-side by the qrcode library (our own output, not user input)
}

const SCHEMES: Record<string, { a: string; b: string; c: string }> = {
  biru: { a: '#087BF0', b: '#12B7ED', c: '#FFE12E' },
  cyan: { a: '#12B7ED', b: '#087BF0', c: '#FFE12E' },
  kuning: { a: '#087BF0', b: '#FFE12E', c: '#12B7ED' },
  netral: { a: '#0B2356', b: '#9DB3D3', c: '#D9E5F3' },
}

export function CardFront({ d, s, b, schoolName, sample }: { d: CardData; s: CardTemplateSettings; b: Branding; schoolName: string; sample?: boolean }) {
  const c = SCHEMES[s.scheme] ?? SCHEMES.biru!
  const logo = publicFileUrl(b.logoFileId) ?? `${P}/icon.svg`
  return (
    <div className={`scard scard--${s.orientation}`} style={{ '--ca': c.a, '--cb': c.b, '--cc': c.c } as React.CSSProperties}>
      <div className="scard__deco" aria-hidden="true" />
      <div className="scard__top">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img className="scard__logo" src={logo} alt="" />
        <div className="scard__school">
          <strong>{(b.shortName || schoolName).toUpperCase()}</strong>
          {b.city ? <span>{b.city.toUpperCase()}</span> : null}
          <i />
          <em>KARTU SISWA</em>
        </div>
      </div>
      <div className="scard__mid">
        {s.show.photo ? (
          <div className="scard__photo">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            {d.photo ? <img src={sample ? d.photo : fileUrl(d.photo)!} alt="" /> : <span>Foto</span>}
          </div>
        ) : null}
        <div className="scard__data">
          <b>{d.name.toUpperCase()}</b>
          <dl>
            {s.show.nis ? (
              <>
                <dt>NIS</dt>
                <dd>{d.nis ?? '—'}</dd>
              </>
            ) : null}
            {s.show.nisn ? (
              <>
                <dt>NISN</dt>
                <dd>{d.nisn ?? '—'}</dd>
              </>
            ) : null}
            {s.show.entryYear ? (
              <>
                <dt>Angkatan</dt>
                <dd>{d.entryYear ?? '—'}</dd>
              </>
            ) : null}
            {s.show.homeroom ? (
              <>
                <dt>Kelas</dt>
                <dd>{d.homeroom ?? '—'}</dd>
              </>
            ) : null}
          </dl>
          <small>
            No. {d.cardNo} · s.d. {fmtDate(d.validUntil, undefined, true)}
          </small>
        </div>
        <div className="scard__qr">
          <div dangerouslySetInnerHTML={{ __html: d.qr }} />
          <span>{sample ? 'QR CONTOH' : 'Verifikasi kartu'}</span>
        </div>
      </div>
    </div>
  )
}

export function CardBack({ s, b, schoolName }: { s: CardTemplateSettings; b: Branding; schoolName: string }) {
  const hero = publicFileUrl(b.heroFileId)
  const logo = publicFileUrl(b.logoFileId) ?? `${P}/icon.svg`
  const c = SCHEMES[s.scheme] ?? SCHEMES.biru!
  return (
    <div className={`scard scard--back scard--${s.orientation}`} style={{ '--ca': c.a, '--cb': c.b, '--cc': c.c, backgroundImage: hero ? `linear-gradient(90deg, rgba(255,255,255,.1), rgba(255,255,255,.92) 55%), url(${hero})` : undefined } as React.CSSProperties}>
      <div className="scard__back">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img className="scard__logo" src={logo} alt="" />
        <strong>{(b.shortName || schoolName).toUpperCase()}</strong>
        {b.city ? <span>{b.city.toUpperCase()}</span> : null}
        <small>{b.address || '[Alamat sekolah]'}</small>
        <small>{[b.phone, b.email].filter(Boolean).join(' · ') || '[Kontak sekolah]'}</small>
        {s.backText ? <p>{s.backText}</p> : null}
      </div>
    </div>
  )
}
